for (const t of cases) {
  const r = spawnSync('/workspace/dataset/test13_executable',
    ['--a', t.a ?? '', '--b', t.b ?? '', '--c', t.c ?? ''], {encoding:'utf8'});
  console.log('##### ' + t.n + ' (code ' + r.status + ')');
  console.log(JSON.stringify({a:t.a,b:t.b,c:t.c}));
