// Character classification helpers.
//
// Everything here works on single code points through `charCodeAt` /
// `codePointAt` so that the parser never needs pattern-matching machinery.

const SPACE = 0x20;
const TAB = 0x09;
const LF = 0x0a;
const CR = 0x0d;
const VT = 0x0b;
const FF = 0x0c;

export const CH = {
  TAB: '\t',
  LF: '\n',
  CR: '\r',
  SPACE: ' ',
};

/** ' ' or '\t' -- horizontal whitespace only. */
export function isSpaceOrTab(ch) {
  return ch === ' ' || ch === '\t';
}

/** Mirrors Python's `str.isspace()` for the code points markdown cares about. */
export function isWhitespace(ch) {
  if (ch === undefined || ch === '') return false;
  const c = ch.charCodeAt(0);
  return c === SPACE || c === TAB || c === LF || c === CR || c === VT || c === FF ||
    c === 0x1c || c === 0x1d || c === 0x1e || c === 0x1f || c === 0x85 ||
    c === 0xa0 || c === 0x1680 || (c >= 0x2000 && c <= 0x200a) ||
    c === 0x2028 || c === 0x2029 || c === 0x202f || c === 0x205f || c === 0x3000;
}

export function isDigit(ch) {
  if (ch === undefined || ch === '') return false;
  const c = ch.charCodeAt(0);
  return c >= 0x30 && c <= 0x39;
}

export function isHexDigit(ch) {
  if (ch === undefined || ch === '') return false;
  const c = ch.charCodeAt(0);
  return (c >= 0x30 && c <= 0x39) || (c >= 0x41 && c <= 0x46) || (c >= 0x61 && c <= 0x66);
}

export function isAsciiLetter(ch) {
  if (ch === undefined || ch === '') return false;
  const c = ch.charCodeAt(0);
  return (c >= 0x41 && c <= 0x5a) || (c >= 0x61 && c <= 0x7a);
}

export function isAsciiAlnum(ch) {
  return isAsciiLetter(ch) || isDigit(ch);
}

// Code point ranges treated as "letters" so that `\w` style look-behinds behave
// like Python's unicode-aware character classes. Only scripts that realistically
// show up in documents are listed; anything outside is punctuation/symbol.
const LETTER_RANGES = [
  [0x00aa, 0x00aa], [0x00b5, 0x00b5], [0x00ba, 0x00ba],
  [0x00c0, 0x00d6], [0x00d8, 0x00f6], [0x00f8, 0x02af],
  [0x0370, 0x0373], [0x0376, 0x0377], [0x037a, 0x037d], [0x037f, 0x037f],
  [0x0386, 0x0386], [0x0388, 0x03ff],
  [0x0400, 0x0481], [0x048a, 0x052f],
  [0x0531, 0x0556], [0x0561, 0x0587],
  [0x05d0, 0x05ea], [0x05ef, 0x05f2],
  [0x0620, 0x064a], [0x066e, 0x066f], [0x0671, 0x06d3], [0x06fa, 0x06fc],
  [0x0710, 0x072f], [0x0750, 0x077f],
  [0x0900, 0x0939], [0x093d, 0x093d], [0x0950, 0x0950], [0x0958, 0x0961],
  [0x0985, 0x09b9], [0x0a05, 0x0a39], [0x0a85, 0x0ab9], [0x0b05, 0x0b39],
  [0x0b85, 0x0bb9], [0x0c05, 0x0c39], [0x0c85, 0x0cb9], [0x0d05, 0x0d3a],
  [0x0d85, 0x0dc6], [0x0e01, 0x0e30], [0x0e32, 0x0e33], [0x0e40, 0x0e46],
  [0x0e81, 0x0eb0], [0x0f40, 0x0f6c], [0x1000, 0x102a],
  [0x10a0, 0x10ff], [0x1100, 0x11ff],
  [0x1200, 0x135a], [0x13a0, 0x13f5],
  [0x1e00, 0x1fff],
  [0x2c00, 0x2c5e], [0x2c60, 0x2ce4],
  [0x3005, 0x3006], [0x3031, 0x3035],
  [0x3041, 0x3096], [0x309d, 0x309f],
  [0x30a1, 0x30fa], [0x30fc, 0x30ff],
  [0x3105, 0x312f], [0x3131, 0x318e],
  [0x31f0, 0x31ff],
  [0x3400, 0x4dbf], [0x4e00, 0x9fff],
  [0xa000, 0xa48c],
  [0xac00, 0xd7a3],
  [0xf900, 0xfa6d], [0xfa70, 0xfad9],
  [0xfb00, 0xfb17],
  [0xff21, 0xff3a], [0xff41, 0xff5a], [0xff66, 0xffdc],
  [0x20000, 0x2a6df], [0x2a700, 0x2ebe0],
];

function inRanges(code, ranges) {
  let lo = 0;
  let hi = ranges.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const r = ranges[mid];
    if (code < r[0]) hi = mid - 1;
    else if (code > r[1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/** Unicode-ish letter test (no ASCII digits). */
export function isLetter(ch) {
  if (ch === undefined || ch === '') return false;
  if (isAsciiLetter(ch)) return true;
  const code = ch.codePointAt(0);
  if (code < 0x00aa) return false;
  return inRanges(code, LETTER_RANGES);
}

/**
 * Equivalent of Python's `\w`: letters, digits and underscore, unicode aware.
 * Used by the "smart emphasis" look-arounds.
 */
export function isWordChar(ch) {
  if (ch === undefined || ch === '') return false;
  if (ch === '_') return true;
  if (isDigit(ch)) return true;
  return isLetter(ch);
}

/** Expand tabs the way Python's `str.expandtabs(n)` does. */
export function expandTabs(text, tabLength) {
  if (text.indexOf('\t') === -1) return text;
  let out = '';
  let column = 0;
  for (const ch of text) {
    if (ch === '\t') {
      const width = tabLength - (column % tabLength);
      out += ' '.repeat(width);
      column += width;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      column = 0;
    } else {
      out += ch;
      column += 1;
    }
  }
  return out;
}

/** Python's `str.strip()` restricted to the whitespace markdown produces. */
export function strip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isWhitespace(text[start])) start += 1;
  while (end > start && isWhitespace(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

export function lstrip(text) {
  let start = 0;
  while (start < text.length && isWhitespace(text[start])) start += 1;
  return text.slice(start);
}

export function rstrip(text) {
  let end = text.length;
  while (end > 0 && isWhitespace(text[end - 1])) end -= 1;
  return text.slice(0, end);
}

/** Strip only the characters present in `chars`. */
export function stripChars(text, chars) {
  let start = 0;
  let end = text.length;
  while (start < end && chars.indexOf(text[start]) !== -1) start += 1;
  while (end > start && chars.indexOf(text[end - 1]) !== -1) end -= 1;
  return text.slice(start, end);
}

export function rstripChars(text, chars) {
  let end = text.length;
  while (end > 0 && chars.indexOf(text[end - 1]) !== -1) end -= 1;
  return text.slice(0, end);
}

/** True when every character is whitespace (or the string is empty). */
export function isBlank(text) {
  for (let i = 0; i < text.length; i += 1) {
    if (!isWhitespace(text[i])) return false;
  }
  return true;
}

/** Number of leading spaces (tabs already expanded upstream). */
export function countLeadingSpaces(line) {
  let n = 0;
  while (n < line.length && line[n] === ' ') n += 1;
  return n;
}

