// Shared constants mirroring the sentinel values used by the reference
// implementation, plus the block level element list that drives raw HTML
// handling and the "prettify" whitespace pass.

export const STX = '';
export const ETX = '';

export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';

export const TAB_LENGTH = 4;

export function inlinePlaceholder(index) {
  return INLINE_PLACEHOLDER_PREFIX + index + ETX;
}

export function htmlPlaceholder(index) {
  return HTML_PLACEHOLDER_PREFIX + index + ETX;
}

/** Characters a backslash may escape. Anything else keeps its backslash. */
export const ESCAPED_CHARS = [
  '\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '>', '#', '+', '-', '.', '!',
];

export const BLOCK_LEVEL_ELEMENTS = new Set([
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  // Not block level per the spec but treated as such by the reference parser.
  'canvas', 'colgroup', 'dd', 'body', 'dt', 'group', 'iframe', 'li', 'legend',
  'math', 'map', 'noscript', 'object', 'output', 'progress', 'script',
  'style', 'summary', 'tbody', 'td', 'textarea', 'tfoot', 'th', 'thead', 'tr',
  'video',
]);

export function isBlockLevel(tag) {
  if (typeof tag !== 'string') return false;
  let name = tag.toLowerCase();
  while (name.endsWith('/')) name = name.slice(0, -1);
  return BLOCK_LEVEL_ELEMENTS.has(name);
}

/** HTML elements that never have a closing tag. */
export const EMPTY_TAGS = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

