// A minimal ElementTree work-alike.
//
// The node shape (tag / attrib / text / tail / children) is what makes it
// possible to reproduce the reference serializer's whitespace exactly: the
// "prettify" pass sets `text` and `tail` to newlines and the serializer simply
// writes them back out.

/** Text that must not be re-scanned for inline markup (code spans etc.). */
export class AtomicString extends String {}

export function atomic(value) {
  return new AtomicString(value);
}

export function isAtomic(value) {
  return value instanceof AtomicString;
}

export class Element {
  constructor(tag, attrib) {
    this.tag = tag;
    this.attrib = new Map();
    this.text = null;
    this.tail = null;
    this.children = [];
    if (attrib) {
      for (const [key, value] of Object.entries(attrib)) this.attrib.set(key, value);
    }
  }

  set(key, value) {
    this.attrib.set(key, value);
    return this;
  }

  get(key, fallback = null) {
    return this.attrib.has(key) ? this.attrib.get(key) : fallback;
  }

  has(key) {
    return this.attrib.has(key);
  }

  append(child) {
    this.children.push(child);
    return child;
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
    return child;
  }

  remove(child) {
    const at = this.children.indexOf(child);
    if (at !== -1) this.children.splice(at, 1);
  }

  extend(items) {
    for (const item of items) this.children.push(item);
  }

  get length() {
    return this.children.length;
  }

  child(index) {
    if (index < 0) return this.children[this.children.length + index];
    return this.children[index];
  }

  /** Depth first iteration, optionally filtered by tag. */
  *iter(tag = null) {
    if (tag === null || this.tag === tag) yield this;
    for (const child of this.children) yield* child.iter(tag);
  }
}

export function subElement(parent, tag, attrib) {
  return parent.append(new Element(tag, attrib));
}

/** Locate the parent of `target` starting from `root` (ElementTree has no links). */
export function findParent(root, target) {
  for (const node of root.iter()) {
    if (node.children.indexOf(target) !== -1) return node;
  }
  return null;
}

