// HTML serializer.
//
// Ports the reference implementation's serializer: void elements are written
// with a trailing " /", `<script>`/`<style>` bodies are emitted raw, and text
// escaping is deliberately narrow (quotes are left alone in text nodes but
// escaped inside attribute values).

import { AMP_SUBSTITUTE } from './constants.mjs';

const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

const RAW_TEXT_TAGS = new Set(['script', 'style']);

/** Escape `&`, `<` and `>` in character data. */
export function escapeCdata(text) {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else out += ch;
  }
  return out;
}

/** Escape an attribute value: cdata rules plus quotes and newlines. */
export function escapeAttrib(text) {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else if (ch === '"') out += '&quot;';
    else if (ch === '\n') out += '&#10;';
    else out += ch;
  }
  return out;
}

/**
 * Attribute values coming from the parser have already had their ampersands
 * turned into the substitute sentinel where they were legitimate entities, so
 * only bare `<`, `>` and quotes need escaping here.
 */
function escapeAttribHtml(text) {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else if (ch === '"') out += '&quot;';
    else out += ch;
  }
  return out;
}

function serializeNode(parts, node, inRawText) {
  if (node.tag === null) {
    // A bare text container: emit its text verbatim (already-safe markup).
    if (node.text !== null) parts.push(String(node.text));
    if (node.tail !== null) parts.push(String(node.tail));
    return;
  }

  const tag = node.tag;
  const raw = inRawText || RAW_TEXT_TAGS.has(tag);

  parts.push('<' + tag);
  for (const [key, value] of node.attrib) {
    if (value === null || value === undefined) continue;
    if (value === true) {
      parts.push(' ' + key);
      continue;
    }
    parts.push(' ' + key + '="' + escapeAttribHtml(String(value)) + '"');
  }

  if (node.children.length === 0 && (node.text === null || String(node.text) === '')) {
    if (HTML_EMPTY.has(tag)) {
      parts.push(' />');
    } else {
      parts.push('></' + tag + '>');
    }
  } else {
    parts.push('>');
    if (node.text !== null) {
      parts.push(raw ? String(node.text) : escapeCdata(String(node.text)));
    }
    for (const child of node.children) serializeNode(parts, child, raw);
    parts.push('</' + tag + '>');
  }

  if (node.tail !== null) {
    parts.push(inRawText ? String(node.tail) : escapeCdata(String(node.tail)));
  }
}

export function serialize(root) {
  const parts = [];
  serializeNode(parts, root, false);
  return parts.join('');
}

/** Restore the ampersand sentinel once serialization is done. */
export function restoreAmpersands(text) {
  return text.split(AMP_SUBSTITUTE).join('&');
}

