// Storage for raw HTML fragments pulled out of the document before parsing.
//
// Fragments are replaced by sentinel placeholders so that block and inline
// parsing never sees (or mangles) them; a postprocessor swaps them back in.

import { htmlPlaceholder } from './constants.mjs';

export class HtmlStash {
  constructor() {
    this.rawHtmlBlocks = [];
    this.tagData = [];
  }

  get length() {
    return this.rawHtmlBlocks.length;
  }

  /** Store a fragment and return its placeholder. */
  store(html) {
    const placeholder = this.getPlaceholder(this.rawHtmlBlocks.length);
    this.rawHtmlBlocks.push(html);
    return placeholder;
  }

  /** Replace an already stored fragment in place (used by md_in_html style passes). */
  replace(index, html) {
    this.rawHtmlBlocks[index] = html;
  }

  get(index) {
    return this.rawHtmlBlocks[index];
  }

  getPlaceholder(index) {
    return htmlPlaceholder(index);
  }

  reset() {
    this.rawHtmlBlocks = [];
    this.tagData = [];
  }
}

