// The HTML 4 named-entity subset used when obfuscating e-mail autolinks, plus
// helpers for recognising entity references in running text.

import { isAsciiAlnum, isDigit, isHexDigit } from './chars.mjs';

/** Code point -> entity name (the mapping the reference implementation uses). */
const CODEPOINT_TO_NAME = new Map([
  [34, 'quot'], [38, 'amp'], [60, 'lt'], [62, 'gt'],
  [160, 'nbsp'], [161, 'iexcl'], [162, 'cent'], [163, 'pound'], [164, 'curren'],
  [165, 'yen'], [166, 'brvbar'], [167, 'sect'], [168, 'uml'], [169, 'copy'],
  [170, 'ordf'], [171, 'laquo'], [172, 'not'], [173, 'shy'], [174, 'reg'],
  [175, 'macr'], [176, 'deg'], [177, 'plusmn'], [178, 'sup2'], [179, 'sup3'],
  [180, 'acute'], [181, 'micro'], [182, 'para'], [183, 'middot'], [184, 'cedil'],
  [185, 'sup1'], [186, 'ordm'], [187, 'raquo'], [188, 'frac14'], [189, 'frac12'],
  [190, 'frac34'], [191, 'iquest'], [215, 'times'], [247, 'divide'],
]);

export function codepointToName(code) {
  return CODEPOINT_TO_NAME.has(code) ? CODEPOINT_TO_NAME.get(code) : null;
}

/**
 * If `text` has an entity reference starting at `start`, return its end index
 * (exclusive), otherwise -1. Any `&name;` shape counts -- the reference parser
 * does not validate the name against a table.
 */
export function matchEntity(text, start) {
  if (text[start] !== '&') return -1;
  let i = start + 1;
  if (text[i] === '#') {
    i += 1;
    if (text[i] === 'x' || text[i] === 'X') {
      i += 1;
      const digitsStart = i;
      while (i < text.length && isHexDigit(text[i])) i += 1;
      if (i === digitsStart) return -1;
    } else {
      const digitsStart = i;
      while (i < text.length && isDigit(text[i])) i += 1;
      if (i === digitsStart) return -1;
    }
  } else {
    const nameStart = i;
    while (i < text.length && isAsciiAlnum(text[i])) i += 1;
    if (i === nameStart) return -1;
  }
  return text[i] === ';' ? i + 1 : -1;
}

