// Hand written HTML tag tokenizer.
//
// Only enough of the grammar is implemented to recognise tag boundaries the way
// a browser-grade parser would: quoted attribute values may contain '>',
// comments and declarations are skipped wholesale, and void elements are
// reported so the caller can avoid pushing them on the open-element stack.

import { isAsciiAlnum, isAsciiLetter, isSpaceOrTab, isWhitespace } from './chars.mjs';

export const TAG_START = 'start';
export const TAG_END = 'end';
export const TAG_STARTEND = 'startend';
export const TAG_COMMENT = 'comment';
export const TAG_DECL = 'decl';
export const TAG_PI = 'pi';

function readTagName(text, start) {
  let i = start;
  if (i >= text.length || !isAsciiLetter(text[i])) return null;
  i += 1;
  while (i < text.length) {
    const ch = text[i];
    if (isAsciiAlnum(ch) || ch === '-' || ch === '_' || ch === ':' || ch === '.') i += 1;
    else break;
  }
  return { name: text.slice(start, i).toLowerCase(), end: i };
}

/** Skip an attribute list, honouring quoted values. Returns index of '>' or -1. */
function skipAttributes(text, start) {
  let i = start;
  let quote = null;
  while (i < text.length) {
    const ch = text[i];
    if (quote !== null) {
      if (ch === quote) quote = null;
      i += 1;
      continue;
    }
    if (ch === '"' || ch === "'") {
      quote = ch;
      i += 1;
      continue;
    }
    if (ch === '>') return i;
    if (ch === '<') return -1;
    i += 1;
  }
  return -1;
}

/**
 * Try to read a tag-ish construct at `start`.
 * Returns `{ kind, name, start, end, text }` or null when this is not markup.
 */
export function matchTag(text, start) {
  if (text[start] !== '<') return null;
  const next = text[start + 1];
  if (next === undefined) return null;

  if (next === '!') {
    if (text.startsWith('<!--', start)) {
      const close = text.indexOf('-->', start + 4);
      const end = close === -1 ? text.length : close + 3;
      return { kind: TAG_COMMENT, name: null, start, end, text: text.slice(start, end) };
    }
    if (text.startsWith('<![CDATA[', start)) {
      const close = text.indexOf(']]>', start + 9);
      const end = close === -1 ? text.length : close + 3;
      return { kind: TAG_DECL, name: null, start, end, text: text.slice(start, end) };
    }
    const gt = skipAttributes(text, start + 2);
    if (gt === -1) return null;
    return { kind: TAG_DECL, name: null, start, end: gt + 1, text: text.slice(start, gt + 1) };
  }

  if (next === '?') {
    const close = text.indexOf('>', start + 2);
    const end = close === -1 ? text.length : close + 1;
    return { kind: TAG_PI, name: null, start, end, text: text.slice(start, end) };
  }

  if (next === '/') {
    const nameInfo = readTagName(text, start + 2);
    if (nameInfo === null) return null;
    let i = nameInfo.end;
    while (i < text.length && isWhitespace(text[i])) i += 1;
    if (text[i] !== '>') return null;
    return { kind: TAG_END, name: nameInfo.name, start, end: i + 1, text: text.slice(start, i + 1) };
  }

  const nameInfo = readTagName(text, start + 1);
  if (nameInfo === null) return null;
  const gt = skipAttributes(text, nameInfo.end);
  if (gt === -1) return null;
  const selfClosing = text[gt - 1] === '/';
  return {
    kind: selfClosing ? TAG_STARTEND : TAG_START,
    name: nameInfo.name,
    start,
    end: gt + 1,
    text: text.slice(start, gt + 1),
  };
}

/** True when only spaces/tabs separate `index` from the start of its line. */
export function atLineStart(text, index) {
  let i = index - 1;
  while (i >= 0 && isSpaceOrTab(text[i])) i -= 1;
  return i < 0 || text[i] === '\n';
}

