// Extracts top level raw HTML blocks from a document and replaces them with
// stash placeholders.
//
// Behaviour that matters for output fidelity:
//   * only *block level* elements starting at the beginning of a line open a raw
//     block; inline elements are left for the inline HTML pattern to handle,
//   * consecutive raw blocks each get their own stash entry, and
//   * when a raw block is followed by a blank line, a single newline is kept as
//     part of the stashed fragment, which is what reproduces the blank line in
//     the final document.

import { isBlockLevel, EMPTY_TAGS } from './constants.mjs';
import {
  matchTag, TAG_START, TAG_END, TAG_STARTEND, TAG_COMMENT, TAG_DECL, TAG_PI,
} from './htmltokenizer.mjs';
import { isSpaceOrTab } from './chars.mjs';

const RAW_TEXT_TAGS = new Set(['script', 'style', 'textarea', 'title']);

/** Leading indent of the line containing `index`, or -1 if not at line start. */
function lineStartIndent(text, index) {
  let i = index - 1;
  let spaces = 0;
  while (i >= 0 && isSpaceOrTab(text[i])) {
    spaces += 1;
    i -= 1;
  }
  if (i >= 0 && text[i] !== '\n') return -1;
  return spaces;
}

/**
 * Does a blank line follow position `i`? Returns the number of characters to
 * treat as "belonging" to the block (0 when no blank line follows).
 */
function blankLineFollows(text, i) {
  let j = i;
  while (j < text.length && isSpaceOrTab(text[j])) j += 1;
  if (j >= text.length) return true;
  if (text[j] !== '\n') return false;
  j += 1;
  while (j < text.length && isSpaceOrTab(text[j])) j += 1;
  return j >= text.length || text[j] === '\n';
}

/**
 * Scan forward from an opening tag and return the index just past the matching
 * close tag, tracking nesting. Returns text.length when never closed.
 */
function findElementEnd(text, openTag) {
  const stack = [openTag.name];
  let i = openTag.end;

  if (RAW_TEXT_TAGS.has(openTag.name)) {
    const closing = '</' + openTag.name;
    const at = text.toLowerCase().indexOf(closing, i);
    if (at === -1) return text.length;
    const close = text.indexOf('>', at);
    return close === -1 ? text.length : close + 1;
  }

  while (i < text.length && stack.length > 0) {
    const ch = text[i];
    if (ch !== '<') {
      i += 1;
      continue;
    }
    const tag = matchTag(text, i);
    if (tag === null) {
      i += 1;
      continue;
    }
    if (tag.kind === TAG_START) {
      if (!EMPTY_TAGS.has(tag.name)) stack.push(tag.name);
      i = tag.end;
      continue;
    }
    if (tag.kind === TAG_END) {
      const at = stack.lastIndexOf(tag.name);
      if (at !== -1) {
        stack.length = at;
      }
      i = tag.end;
      if (stack.length === 0) return i;
      continue;
    }
    i = tag.end;
  }
  return i;
}

/**
 * Replace top level raw HTML with placeholders.
 * @param {string} text whole document
 * @param {import('./stash.mjs').HtmlStash} stash
 * @returns {string} document with placeholders
 */
export function extractHtmlBlocks(text, stash) {
  let out = '';
  let i = 0;
  let plain = '';

  const flush = () => {
    if (plain !== '') {
      out += plain;
      plain = '';
    }
  };

  while (i < text.length) {
    const ch = text[i];
    if (ch !== '<') {
      plain += ch;
      i += 1;
      continue;
    }

    const tag = matchTag(text, i);
    if (tag === null) {
      plain += ch;
      i += 1;
      continue;
    }

    const indent = lineStartIndent(text, i);
    const startsLine = indent >= 0 && indent < 4;

    let isRawCandidate = false;
    if (startsLine) {
      if (tag.kind === TAG_COMMENT || tag.kind === TAG_DECL || tag.kind === TAG_PI) {
        isRawCandidate = true;
      } else if (tag.kind === TAG_STARTEND || tag.kind === TAG_START) {
        isRawCandidate = isBlockLevel(tag.name);
      }
    }

    if (!isRawCandidate) {
      plain += ch;
      i += 1;
      continue;
    }

    let end;
    if (tag.kind === TAG_START && !EMPTY_TAGS.has(tag.name)) {
      end = findElementEnd(text, tag);
    } else {
      end = tag.end;
    }

    let raw = text.slice(i, end);
    if (blankLineFollows(text, end)) raw += '\n';

    flush();
    out += '\n\n' + stash.store(raw) + '\n\n';
    i = end;
  }

  flush();
  return out;
}

