// Hand written recognisers for the block level constructs.
//
// Each function mirrors one pattern from the reference implementation. They all
// work by direct index arithmetic so no pattern-matching engine is involved.

import {
  countLeadingSpaces, isBlank, isDigit, isSpaceOrTab, isWhitespace, rstrip, strip,
} from './chars.mjs';
import { TAB_LENGTH } from './constants.mjs';

/** Index just past the end of the line starting at `start` (excludes '\n'). */
export function lineEnd(text, start) {
  const at = text.indexOf('\n', start);
  return at === -1 ? text.length : at;
}

/** Every index in `text` that begins a line. */
export function lineStarts(text) {
  const starts = [0];
  let at = text.indexOf('\n');
  while (at !== -1) {
    starts.push(at + 1);
    at = text.indexOf('\n', at + 1);
  }
  return starts;
}

/** `^[ ]{0,3}\d+\.[ ]+(.*)` */
export function matchOrderedItem(line) {
  const indent = countLeadingSpaces(line);
  if (indent > TAB_LENGTH - 1) return null;
  let i = indent;
  const digitsStart = i;
  while (i < line.length && isDigit(line[i])) i += 1;
  if (i === digitsStart) return null;
  const number = line.slice(digitsStart, i);
  if (line[i] !== '.') return null;
  i += 1;
  if (line[i] !== ' ') return null;
  while (i < line.length && line[i] === ' ') i += 1;
  return { number, marker: number + '.', content: line.slice(i) };
}

/** `^[ ]{0,3}[*+-][ ]+(.*)` */
export function matchUnorderedItem(line) {
  const indent = countLeadingSpaces(line);
  if (indent > TAB_LENGTH - 1) return null;
  let i = indent;
  const bullet = line[i];
  if (bullet !== '*' && bullet !== '+' && bullet !== '-') return null;
  i += 1;
  if (line[i] !== ' ') return null;
  while (i < line.length && line[i] === ' ') i += 1;
  return { marker: bullet, content: line.slice(i) };
}

/** `^[ ]{0,3}((\d+\.)|[*+-])[ ]+(.*)` -- either list flavour. */
export function matchAnyItem(line) {
  return matchOrderedItem(line) || matchUnorderedItem(line);
}

/** `^[ ]{tab,2*tab-1}((\d+\.)|[*+-])[ ]+.*` -- an indented (nested) item. */
export function matchIndentedItem(line) {
  const indent = countLeadingSpaces(line);
  if (indent < TAB_LENGTH || indent > TAB_LENGTH * 2 - 1) return null;
  const rest = line.slice(indent);
  const trimmed = { ...{}, };
  void trimmed;
  const asOrdered = matchOrderedItem(rest);
  if (asOrdered !== null) return asOrdered;
  return matchUnorderedItem(rest);
}

/**
 * `(?:^|\n)(#{1,6})((?:\\.|[^\\])*?)#*(?:\n|$)`
 * Returns `{ start, end, level, header }` or null.
 */
export function searchHashHeader(block) {
  for (const start of lineStarts(block)) {
    let i = start;
    let hashes = 0;
    while (i < block.length && block[i] === '#' && hashes < 6) {
      hashes += 1;
      i += 1;
    }
    if (hashes === 0) continue;
    const stop = lineEnd(block, i);
    let rest = block.slice(i, stop);
    // `#*` is greedy, so trailing hashes are dropped unless backslash escaped.
    let end = rest.length;
    while (end > 0 && rest[end - 1] === '#') {
      if (end >= 2 && rest[end - 2] === '\\') break;
      end -= 1;
    }
    rest = rest.slice(0, end);
    return {
      // The leading newline is part of the match.
      start: start === 0 ? 0 : start - 1,
      end: stop < block.length ? stop + 1 : stop,
      level: hashes,
      header: strip(rest),
    };
  }
  return null;
}

/** `^.*?\n[=-]+[ ]*(\n|$)` anchored at the start of the block. */
export function matchSetextHeader(block) {
  const firstBreak = block.indexOf('\n');
  if (firstBreak === -1) return null;
  const secondStart = firstBreak + 1;
  const secondEnd = lineEnd(block, secondStart);
  const underline = block.slice(secondStart, secondEnd);
  let i = 0;
  while (i < underline.length && (underline[i] === '=' || underline[i] === '-')) i += 1;
  if (i === 0) return null;
  for (let j = i; j < underline.length; j += 1) {
    if (underline[j] !== ' ') return null;
  }
  return { level: underline[0] === '=' ? 1 : 2 };
}

/**
 * `^[ ]{0,3}((-+[ ]{0,2}){3,}|(_+[ ]{0,2}){3,}|(\*+[ ]{0,2}){3,})$`
 * Returns `{ start, end }` of the first horizontal rule line.
 */
export function searchHorizontalRule(block) {
  for (const start of lineStarts(block)) {
    const stop = lineEnd(block, start);
    const indent = countLeadingSpaces(block.slice(start, stop));
    if (indent > 3) continue;
    let i = start + indent;
    if (i >= stop) continue;
    const marker = block[i];
    if (marker !== '-' && marker !== '_' && marker !== '*') continue;
    let groups = 0;
    let ok = true;
    while (i < stop) {
      if (block[i] !== marker) { ok = false; break; }
      while (i < stop && block[i] === marker) i += 1;
      let spaces = 0;
      while (i < stop && block[i] === ' ' && spaces < 2) {
        spaces += 1;
        i += 1;
      }
      groups += 1;
    }
    if (ok && i === stop && groups >= 3) return { start, end: stop };
  }
  return null;
}

/** `(^|\n)[ ]{0,3}>[ ]?(.*)` -- returns `{ start, contentStart }` of the match. */
export function searchBlockQuote(block) {
  for (const start of lineStarts(block)) {
    const stop = lineEnd(block, start);
    const indent = countLeadingSpaces(block.slice(start, stop));
    if (indent > 3) continue;
    const at = start + indent;
    if (block[at] !== '>') continue;
    return { start: start === 0 ? 0 : start - 1, lineStart: start };
  }
  return null;
}

/** Strip one level of `> ` from a quoted line (the reference `clean`). */
export function cleanQuoteLine(line) {
  if (strip(line) === '>') return '';
  const indent = countLeadingSpaces(line);
  if (indent <= 3 && line[indent] === '>') {
    let i = indent + 1;
    if (line[i] === ' ') i += 1;
    return strip(line.slice(i));
  }
  return line;
}

/**
 * Reference definition: `[id]: url "title"` possibly wrapped onto a second
 * line. Returns `{ start, end, id, link, title }` or null.
 */
export function searchReference(block) {
  const starts = lineStarts(block);
  for (const start of starts) {
    const stop = lineEnd(block, start);
    const line = block.slice(start, stop);
    const indent = countLeadingSpaces(line);
    if (indent > 3) continue;
    let i = indent;
    if (line[i] !== '[') continue;
    i += 1;
    const idStart = i;
    while (i < line.length && line[i] !== '[' && line[i] !== ']') i += 1;
    if (line[i] !== ']') continue;
    const id = line.slice(idStart, i);
    i += 1;
    if (line[i] !== ':') continue;
    i += 1;
    while (i < line.length && line[i] === ' ') i += 1;

    // The URL may live on the following line.
    let cursor = start + i;
    let end = stop;
    if (i >= line.length) {
      if (stop >= block.length) continue;
      const nextStart = stop + 1;
      const nextStop = lineEnd(block, nextStart);
      let k = nextStart;
      while (k < nextStop && block[k] === ' ') k += 1;
      cursor = k;
      end = nextStop;
      if (cursor >= nextStop) continue;
    }

    const urlStart = cursor;
    while (cursor < end && !isWhitespace(block[cursor])) cursor += 1;
    const link = block.slice(urlStart, cursor);
    if (link === '') continue;

    while (cursor < end && isSpaceOrTab(block[cursor])) cursor += 1;
    let title = null;
    let searchEnd = end;

    // Title may also be pushed onto the next line.
    if (cursor >= end && end < block.length) {
      const nextStart = end + 1;
      const nextStop = lineEnd(block, nextStart);
      let k = nextStart;
      while (k < nextStop && block[k] === ' ') k += 1;
      const opener = block[k];
      if (opener === '"' || opener === "'" || opener === '(') {
        cursor = k;
        searchEnd = nextStop;
      }
    }

    if (cursor < searchEnd) {
      const opener = block[cursor];
      const closer = opener === '(' ? ')' : opener;
      if (opener === '"' || opener === "'" || opener === '(') {
        const close = block.lastIndexOf(closer, searchEnd - 1);
        if (close > cursor) {
          const after = block.slice(close + 1, searchEnd);
          if (isBlank(after)) {
            title = block.slice(cursor + 1, close);
            cursor = searchEnd;
          }
        }
      }
    }

    if (!isBlank(block.slice(cursor, searchEnd))) continue;

    return {
      start,
      end: searchEnd,
      id: strip(id).toLowerCase(),
      link: stripAngles(link),
      title,
    };
  }
  return null;
}

function stripAngles(url) {
  let out = url;
  while (out.startsWith('<')) out = out.slice(1);
  while (out.endsWith('>')) out = out.slice(0, -1);
  return out;
}

/** Escape the three characters that matter inside `<code>`. */
export function codeEscape(text) {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else out += ch;
  }
  return out;
}

/**
 * Remove `length` spaces of indentation, stopping at the first line that is
