// The block level parser: turns a document into an element tree by handing each
// "block" (text separated by blank lines) to the first processor that claims it.

import { Element } from './element.mjs';

/** Parser state stack. Only the top of the stack is ever inspected. */
export class State {
  constructor() {
    this.stack = [];
  }

  set(state) {
    this.stack.push(state);
  }

  reset() {
    this.stack.pop();
  }

  isstate(state) {
    if (this.stack.length === 0) return false;
    return this.stack[this.stack.length - 1] === state;
  }
}

export class BlockParser {
  constructor(md) {
    this.md = md;
    this.state = new State();
    this.processors = [];
    this.root = null;
  }

  /** Register a processor; higher priority runs first. */
  register(processor, name, priority) {
    this.processors.push({ processor, name, priority });
    this.processors.sort((a, b) => b.priority - a.priority);
  }

  deregister(name) {
    this.processors = this.processors.filter((entry) => entry.name !== name);
  }

  parseDocument(lines) {
    this.root = new Element(this.md.docTag);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  parseChunk(parent, text) {
    this.parseBlocks(parent, text.split('\n\n'));
  }

  parseBlocks(parent, blocks) {
    while (blocks.length > 0) {
      let handled = false;
      for (const { processor } of this.processors) {
        if (processor.test(parent, blocks[0])) {
          if (processor.run(parent, blocks) !== false) {
            handled = true;
            break;
          }
        }
      }
      if (!handled) {
        // No processor accepted the block; drop it to avoid spinning forever.
        blocks.shift();
      }
    }
  }
}

/** Common helpers shared by every block processor. */
export class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = 4;
  }

  lastChild(parent) {
    if (parent.children.length === 0) return null;
    return parent.children[parent.children.length - 1];
  }

  test() {
    return false;
  }

  run() {
    return false;
  }
}

