// Core block processors, registered in the same priority order the reference
// implementation uses:
//   empty 100, indent 90, code 80, hashheader 70, setextheader 60, hr 50,
//   olist 40, ulist 30, quote 20, reference 15, paragraph 10.

import { BlockProcessor } from './blockparser.mjs';
import { Element, atomic, subElement } from './element.mjs';
import { TAB_LENGTH } from './constants.mjs';
import { isBlank, lstrip, rstrip, rstripChars, strip } from './chars.mjs';
import {
  cleanQuoteLine, codeEscape, detab, looseDetab, matchAnyItem, matchIndentedItem,
  matchOrderedItem, matchSetextHeader, matchUnorderedItem, searchBlockQuote,
  searchHashHeader, searchHorizontalRule, searchReference,
} from './blockpatterns.mjs';

const INDENT = ' '.repeat(TAB_LENGTH);

function isCodeSibling(sibling) {
  return sibling !== null && sibling.tag === 'pre' &&
    sibling.children.length > 0 && sibling.children[0].tag === 'code';
}

export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block === '' || block.startsWith('\n');
  }

  run(parent, blocks) {
    const block = blocks.shift();
    let filler = '\n\n';
    if (block !== '') {
      filler = '\n';
      const theRest = block.slice(1);
      if (theRest !== '') blocks.unshift(theRest);
    }
    const sibling = this.lastChild(parent);
    if (isCodeSibling(sibling)) {
      const code = sibling.children[0];
      code.text = atomic(String(code.text) + filler);
    }
    return undefined;
  }
}

export class ListIndentProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.itemTypes = ['li'];
    this.listTypes = ['ul', 'ol'];
  }

  test(parent, block) {
    if (!block.startsWith(INDENT)) return false;
    if (this.parser.state.isstate('detabbed')) return false;
    if (this.itemTypes.includes(parent.tag)) return true;
    const last = this.lastChild(parent);
    return last !== null && this.listTypes.includes(last.tag);
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const [level, sibling] = this.getLevel(parent, block);
    block = looseDetab(block, level);

    this.parser.state.set('detabbed');
    if (this.itemTypes.includes(parent.tag)) {
      const last = this.lastChild(parent);
      if (last !== null && this.listTypes.includes(last.tag)) {
        this.parser.parseBlocks(last, [block]);
      } else {
        this.parser.parseBlocks(parent, [block]);
      }
    } else if (this.itemTypes.includes(sibling.tag)) {
      this.parser.parseBlocks(sibling, [block]);
    } else {
      const last = this.lastChild(sibling);
      if (last !== null && this.itemTypes.includes(last.tag)) {
        this.parser.parseBlocks(last, [block]);
      } else {
        const li = subElement(sibling, 'li');
        this.parser.parseBlocks(li, [block]);
      }
    }
    this.parser.state.reset();
    return undefined;
  }

  getLevel(parent, block) {
    let indentLevel = 0;
    let i = 0;
    while (block.startsWith(INDENT, i)) {
      indentLevel += 1;
      i += TAB_LENGTH;
    }
    let level = this.parser.state.isstate('list') ? 1 : 0;
    let node = parent;
    while (indentLevel > level) {
      const child = this.lastChild(node);
      if (child !== null &&
        (this.listTypes.includes(child.tag) || this.itemTypes.includes(child.tag))) {
        if (this.listTypes.includes(child.tag)) level += 1;
        node = child;
      } else {
        break;
      }
    }
    return [level, node];
  }
}

export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block.startsWith(INDENT);
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    let block = blocks.shift();
    let theRest = '';
    if (isCodeSibling(sibling)) {
      const code = sibling.children[0];
      [block, theRest] = detab(block);
      code.text = atomic(String(code.text) + '\n' + codeEscape(rstrip(block)) + '\n');
    } else {
      const pre = subElement(parent, 'pre');
      const code = subElement(pre, 'code');
      [block, theRest] = detab(block);
      code.text = atomic(codeEscape(rstrip(block)) + '\n');
    }
    if (theRest !== '') blocks.unshift(theRest);
    return undefined;
  }
}

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return searchHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = searchHashHeader(block);
    if (m === null) {
      blocks.unshift(block);
      return false;
    }
    const before = block.slice(0, m.start);
    const after = block.slice(m.end);
    if (before !== '') this.parser.parseBlocks(parent, [before]);
    const h = subElement(parent, 'h' + m.level);
    h.text = m.header;
    if (after !== '') blocks.unshift(after);
    return undefined;
  }
}

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block) !== null;
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const m = matchSetextHeader(lines.join('\n'));
    const level = m === null ? 2 : m.level;
    const h = subElement(parent, 'h' + level);
    h.text = strip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
    return undefined;
  }
}

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    this.match = searchHorizontalRule(block);
    return this.match !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this.match;
    const prelines = rstripChars(block.slice(0, match.start), '\n');
    if (prelines !== '') this.parser.parseBlocks(parent, [prelines]);
    subElement(parent, 'hr');
    let postlines = block.slice(match.end);
    let cut = 0;
    while (cut < postlines.length && postlines[cut] === '\n') cut += 1;
    postlines = postlines.slice(cut);
    if (postlines !== '') blocks.unshift(postlines);
    return undefined;
  }
}

export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.tag = 'ol';
    this.startswith = '1';
    this.lazyOl = true;
    this.siblingTags = ['ol', 'ul'];
  }

  matchStart(line) {
    return matchOrderedItem(line);
  }

  test(parent, block) {
    const firstLine = block.split('\n', 1)[0];
    return this.matchStart(firstLine) !== null;
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;

    if (sibling !== null && this.siblingTags.includes(sibling.tag)) {
      lst = sibling;
      const lastItem = lst.children[lst.children.length - 1];
      if (lastItem !== undefined && lastItem.text !== null && String(lastItem.text) !== '') {
        const p = new Element('p');
        p.text = lastItem.text;
        lastItem.text = '';
        lastItem.insert(0, p);
      }
      if (lastItem !== undefined) {
        const lch = this.lastChild(lastItem);
        if (lch !== null && lch.tail !== null && String(lch.tail) !== '') {
          const p = subElement(lastItem, 'p');
          p.text = lstrip(String(lch.tail));
          lch.tail = '';
        }
      }
      const li = subElement(lst, 'li');
      this.parser.state.set('looselist');
      const firstitem = items.shift();
      this.parser.parseBlocks(li, [firstitem]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      lst = parent;
    } else {
      lst = subElement(parent, this.tag);
      if (!this.lazyOl && this.startswith !== '1') lst.set('start', this.startswith);
    }

    this.parser.state.set('list');
    for (const item of items) {
      if (item.startsWith(INDENT)) {
        this.parser.parseBlocks(lst.children[lst.children.length - 1], [item]);
      } else {
        const li = subElement(lst, 'li');
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
    return undefined;
  }

  getItems(block) {
    const items = [];
    for (const line of block.split('\n')) {
      const child = matchAnyItem(line);
      if (child !== null) {
        if (items.length === 0 && this.tag === 'ol') {
          const ordered = matchOrderedItem(line);
          if (ordered !== null) this.startswith = ordered.number;
        }
        items.push(child.content);
      } else if (matchIndentedItem(line) !== null) {
        if (items.length > 0 && items[items.length - 1].startsWith(INDENT)) {
          items[items.length - 1] += '\n' + line;
        } else {
          items.push(line);
        }
      } else if (items.length === 0) {
        items.push(line);
      } else {
        items[items.length - 1] += '\n' + line;
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.tag = 'ul';
    this.siblingTags = ['ul', 'ol'];
  }

  matchStart(line) {
    return matchUnorderedItem(line);
  }
}

export class BlockQuoteProcessor extends BlockProcessor {
  test(parent, block) {
    return searchBlockQuote(block) !== null;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const m = searchBlockQuote(block);
    if (m !== null) {
      const before = block.slice(0, m.start);
      this.parser.parseBlocks(parent, [before]);
      block = block
        .slice(m.start === 0 ? 0 : m.start + 1)
        .split('\n')
        .map((line) => cleanQuoteLine(line))
        .join('\n');
    }
    const sibling = this.lastChild(parent);
    let quote;
    if (sibling !== null && sibling.tag === 'blockquote') quote = sibling;
    else quote = subElement(parent, 'blockquote');

    this.parser.state.set('blockquote');
    this.parser.parseChunk(quote, block);
    this.parser.state.reset();
    return undefined;
  }
}

export class ReferenceProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = searchReference(block);
    if (m !== null) {
      this.parser.md.references.set(m.id, { href: m.link, title: m.title });
      const after = block.slice(m.end);
      if (!isBlank(after)) {
        let cut = 0;
        while (cut < after.length && after[cut] === '\n') cut += 1;
        blocks.unshift(after.slice(cut));
      }
      const before = block.slice(0, m.start);
      if (!isBlank(before)) blocks.unshift(rstripChars(before, '\n'));
      return true;
    }
    blocks.unshift(block);
    return false;
  }
}

export class ParagraphProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (!isBlank(block)) {
      if (this.parser.state.isstate('list')) {
        const sibling = this.lastChild(parent);
        if (sibling !== null) {
          if (sibling.tail !== null && String(sibling.tail) !== '') {
            sibling.tail = String(sibling.tail) + '\n' + block;
          } else {
            sibling.tail = '\n' + block;
          }
        } else if (parent.text !== null && String(parent.text) !== '') {
          parent.text = String(parent.text) + '\n' + block;
        } else {
          parent.text = lstrip(block);
        }
      } else {
        const p = subElement(parent, 'p');
        p.text = lstrip(block);
      }
    }
    return undefined;
  }
}

export function buildBlockParser(md, parser) {
  parser.register(new EmptyBlockProcessor(parser), 'empty', 100);
  parser.register(new ListIndentProcessor(parser), 'indent', 90);
  parser.register(new CodeBlockProcessor(parser), 'code', 80);
  parser.register(new HashHeaderProcessor(parser), 'hashheader', 70);
  parser.register(new SetextHeaderProcessor(parser), 'setextheader', 60);
  parser.register(new HRProcessor(parser), 'hr', 50);
  parser.register(new OListProcessor(parser), 'olist', 40);
  parser.register(new UListProcessor(parser), 'ulist', 30);
  parser.register(new BlockQuoteProcessor(parser), 'quote', 20);
  parser.register(new ReferenceProcessor(parser), 'reference', 15);
  parser.register(new ParagraphProcessor(parser), 'paragraph', 10);
  return parser;
}

