// Emphasis / strong processors.
//
// The reference implementation keeps an ordered list of five patterns per
// delimiter character and, once one matches, only patterns *after* it in the
// list may be used on the captured content. That ordering is what produces the
// distinctive results for inputs such as `*a **b** c*`, so it is preserved here
// verbatim -- including the fact that a successful sub-match does not stop the
// scan from trying the remaining patterns at the new position.

import { Element } from '../element.mjs';
import { isWordChar } from '../chars.mjs';

const SINGLE = 'single';
const DOUBLE = 'double';
const DOUBLE2 = 'double2';

function charAt(data, index) {
  return index >= 0 && index < data.length ? data[index] : undefined;
}

function notWordBefore(data, pos) {
  return !isWordChar(charAt(data, pos - 1));
}

function notWordAfter(data, pos) {
  return !isWordChar(charAt(data, pos));
}

/** `(C)\1{2}(.+?)\1(.*?)\1{2}` -- `***em,strong***` */
function makeEmStrong(c) {
  const triple = c + c + c;
  const double = c + c;
  return (data, pos) => {
    if (!data.startsWith(triple, pos)) return null;
    const bodyStart = pos + 3;
    for (let i = bodyStart + 1; i < data.length; i += 1) {
      if (data[i] !== c) continue;
      for (let j = i + 1; j + 2 <= data.length; j += 1) {
        if (data.startsWith(double, j)) {
          return {
            start: pos,
            end: j + 2,
            groups: [c, data.slice(bodyStart, i), data.slice(i + 1, j)],
          };
        }
      }
    }
    return null;
  };
}

/** `(C)\1{2}(.+?)\1{2}(.*?)\1` -- `***strong,em***` */
function makeStrongEm(c) {
  const triple = c + c + c;
  const double = c + c;
  return (data, pos) => {
    if (!data.startsWith(triple, pos)) return null;
    const bodyStart = pos + 3;
    for (let i = bodyStart + 1; i + 2 <= data.length; i += 1) {
      if (!data.startsWith(double, i)) continue;
      for (let j = i + 2; j < data.length; j += 1) {
        if (data[j] === c) {
          return {
            start: pos,
            end: j + 1,
            groups: [c, data.slice(bodyStart, i), data.slice(i + 2, j)],
          };
        }
      }
    }
    return null;
  };
}

/** `(\*)\1(?!\1)([^*]+?)\1(?!\1)(.+?)\1{3}` -- `**strong*em***` */
function makeStrongEm3(c) {
  const double = c + c;
  const triple = c + c + c;
  return (data, pos) => {
    if (!data.startsWith(double, pos)) return null;
    if (charAt(data, pos + 2) === c) return null;
    const bodyStart = pos + 2;
    for (let i = bodyStart + 1; i < data.length; i += 1) {
      // group 2 may not contain the delimiter
      if (data.slice(bodyStart, i).indexOf(c) !== -1) break;
      if (data[i] !== c) continue;
      if (charAt(data, i + 1) === c) continue;
      for (let j = i + 2; j + 3 <= data.length; j += 1) {
        if (data.startsWith(triple, j)) {
          return {
            start: pos,
            end: j + 3,
            groups: [c, data.slice(bodyStart, i), data.slice(i + 1, j)],
          };
        }
      }
    }
    return null;
  };
}

/** `(\*{2})(.+?)\1` */
function makeStrong(c) {
  const double = c + c;
  return (data, pos) => {
    if (!data.startsWith(double, pos)) return null;
    const bodyStart = pos + 2;
    for (let i = bodyStart + 1; i + 2 <= data.length; i += 1) {
      if (data.startsWith(double, i)) {
        return { start: pos, end: i + 2, groups: [double, data.slice(bodyStart, i)] };
      }
    }
    return null;
  };
}

/** `(\*)([^\*]+)\1` */
function makeEmphasis(c) {
  return (data, pos) => {
    if (data[pos] !== c) return null;
    let i = pos + 1;
    while (i < data.length && data[i] !== c) i += 1;
    if (i === pos + 1 || i >= data.length) return null;
    return { start: pos, end: i + 1, groups: [c, data.slice(pos + 1, i)] };
  };
}

/** `(?<!\w)(_{2})(?!_)(.+?)(?<!_)\1(?!\w)` */
function makeSmartStrong(c) {
  const double = c + c;
  return (data, pos) => {
    if (!notWordBefore(data, pos)) return null;
    if (!data.startsWith(double, pos)) return null;
    if (charAt(data, pos + 2) === c) return null;
    const bodyStart = pos + 2;
    for (let i = bodyStart + 1; i + 2 <= data.length; i += 1) {
      if (!data.startsWith(double, i)) continue;
      if (data[i - 1] === c) continue;
      if (!notWordAfter(data, i + 2)) continue;
      return { start: pos, end: i + 2, groups: [double, data.slice(bodyStart, i)] };
    }
    return null;
  };
}

/** `(?<!\w)(_)(?!_)(.+?)(?<!_)\1(?!\w)` */
function makeSmartEmphasis(c) {
  return (data, pos) => {
    if (!notWordBefore(data, pos)) return null;
    if (data[pos] !== c) return null;
    if (charAt(data, pos + 1) === c) return null;
    const bodyStart = pos + 1;
    for (let i = bodyStart + 1; i < data.length; i += 1) {
      if (data[i] !== c) continue;
      if (data[i - 1] === c) continue;
      if (!notWordAfter(data, i + 1)) continue;
      return { start: pos, end: i + 1, groups: [c, data.slice(bodyStart, i)] };
    }
    return null;
  };
}

/** `(?<!\w)(_)\1(?!\1)(.+?)(?<!\w)\1(?!\1)(.+?)\1{3}(?!\w)` */
function makeSmartStrongEm(c) {
  const double = c + c;
  const triple = c + c + c;
  return (data, pos) => {
    if (!notWordBefore(data, pos)) return null;
    if (!data.startsWith(double, pos)) return null;
    if (charAt(data, pos + 2) === c) return null;
    const bodyStart = pos + 2;
    for (let i = bodyStart + 1; i < data.length; i += 1) {
      if (data[i] !== c) continue;
      if (isWordChar(charAt(data, i - 1))) continue;
      if (charAt(data, i + 1) === c) continue;
      for (let j = i + 2; j + 3 <= data.length; j += 1) {
        if (!data.startsWith(triple, j)) continue;
        if (!notWordAfter(data, j + 3)) continue;
        return {
          start: pos,
          end: j + 3,
          groups: [c, data.slice(bodyStart, i), data.slice(i + 1, j)],
        };
      }
    }
    return null;
  };
}

function buildPatterns(kind) {
  if (kind === '*') {
    return [
      { match: makeEmStrong('*'), builder: DOUBLE, tags: 'strong,em' },
      { match: makeStrongEm('*'), builder: DOUBLE, tags: 'em,strong' },
      { match: makeStrongEm3('*'), builder: DOUBLE2, tags: 'strong,em' },
      { match: makeStrong('*'), builder: SINGLE, tags: 'strong' },
      { match: makeEmphasis('*'), builder: SINGLE, tags: 'em' },
    ];
  }
  return [
    { match: makeEmStrong('_'), builder: DOUBLE, tags: 'strong,em' },
    { match: makeStrongEm('_'), builder: DOUBLE, tags: 'em,strong' },
    { match: makeSmartStrongEm('_'), builder: DOUBLE2, tags: 'strong,em' },
    { match: makeSmartStrong('_'), builder: SINGLE, tags: 'strong' },
    { match: makeSmartEmphasis('_'), builder: SINGLE, tags: 'em' },
  ];
}

export class EmStrongProcessor {
  constructor(kind) {
    this.kind = kind;
    this.patterns = buildPatterns(kind);
  }

  /** Trigger: a bare delimiter character. */
  find(data, startIndex) {
    const at = data.indexOf(this.kind, startIndex);
    return at === -1 ? null : { start: at, end: at + 1 };
  }

  handleMatch(data, trigger) {
    for (let index = 0; index < this.patterns.length; index += 1) {
      const item = this.patterns[index];
      const m = item.match(data, trigger.start);
      if (m !== null) {
        return {
          node: this.buildElement(m, item.builder, item.tags, index),
          start: m.start,
          end: m.end,
        };
      }
    }
    return null;
  }

  buildElement(m, builder, tags, index) {
    if (builder === SINGLE) return this.buildSingle(m, tags, index);
    if (builder === DOUBLE) return this.buildDouble(m, tags, index);
    return this.buildDouble2(m, tags, index);
  }

  buildSingle(m, tag, index) {
    const el = new Element(tag);
    this.parseSubPatterns(m.groups[1], el, null, index);
    return el;
  }

  buildDouble(m, tags, index) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.groups[1], el2, null, index);
    el1.append(el2);
    const rest = m.groups[2];
    if (rest !== undefined && rest !== '') {
      this.parseSubPatterns(rest, el1, el2, index);
    }
    return el1;
  }

  buildDouble2(m, tags, index) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.groups[1], el1, null, index);
    this.parseSubPatterns(m.groups[2], el2, null, index);
    el1.append(el2);
    return el1;
  }

  /**
   * Attach nested emphasis found in `data` to `parent`. Only patterns *after*
   * `idx` are eligible, mirroring the reference implementation.
   */
  parseSubPatterns(data, parent, lastChild, idx) {
    let last = lastChild;
    let offset = 0;
    let pos = 0;
    const attachText = (text) => {
      if (text === '') return;
      if (last !== null) last.tail = (last.tail === null ? '' : last.tail) + text;
      else parent.text = (parent.text === null ? '' : parent.text) + text;
    };

    while (pos < data.length) {
      if (data[pos] !== this.kind) {
        pos += 1;
        continue;
      }
      let matched = false;
      for (let index = 0; index < this.patterns.length; index += 1) {
        if (index <= idx) continue;
        const m = this.patterns[index].match(data, pos);
        if (m === null) continue;
        attachText(data.slice(offset, m.start));
        const el = this.buildElement(m, this.patterns[index].builder,
          this.patterns[index].tags, index);
        parent.append(el);
        last = el;
        offset = m.end;
        pos = m.end;
        matched = true;
      }
      if (!matched) pos += 1;
    }
    attachText(data.slice(offset));
  }
}

/** `((^|(?<=\s))(\*{1,3}|_{1,3})(?=\s|$))` -- delimiters that are just text. */
export function matchNotStrong(data, pos) {
  const { isWhitespace } = notStrongDeps;
  if (pos !== 0 && !isWhitespace(data[pos - 1])) return null;
  const c = data[pos];
  if (c !== '*' && c !== '_') return null;
  let run = 0;
  while (run < 3 && data[pos + run] === c) run += 1;
  for (let take = run; take >= 1; take -= 1) {
    const after = charAt(data, pos + take);
    if (after === undefined || isWhitespace(after)) {
      return { start: pos, end: pos + take, text: data.slice(pos, pos + take) };
    }
  }
  return null;
}

// Injected to keep the whitespace definition in one place.
const notStrongDeps = { isWhitespace: null };

export function configureNotStrong(isWhitespaceFn) {
  notStrongDeps.isWhitespace = isWhitespaceFn;
}

