  parseSubPatterns(data, parent, lastChild, idx) {
    let last = lastChild;
    let offset = 0;
    let pos = 0;
    const attachText = (text) => {
      if (text === '') return;
      if (last !== null) last.tail = (last.tail === null ? '' : last.tail) + text;
      else parent.text = (parent.text === null ? '' : parent.text) + text;
    };

    while (pos < data.length) {
      if (data[pos] !== this.kind) {
        pos += 1;
        continue;
      }
      let matched = false;
      for (let index = 0; index < this.patterns.length; index += 1) {
        if (index <= idx) continue;
        const m = this.patterns[index].match(data, pos);
        if (m === null) continue;
        attachText(data.slice(offset, m.start));
        const el = this.buildElement(m, this.patterns[index].builder,
          this.patterns[index].tags, index);
        parent.append(el);
        last = el;
        offset = m.end;
        pos = m.end;
        matched = true;
      }
      if (!matched) pos += 1;
    }
    attachText(data.slice(offset));
  }
