// Link, image and reference processors.
//
// Bracket and parenthesis matching is done by counting, which is how the
// reference implementation handles nesting such as `[![alt](img)](href)`.

import { Element, atomic } from '../element.mjs';
import { isWhitespace, strip } from '../chars.mjs';

/**
 * Read the label between `[` and its matching `]`, honouring nesting.
 * `index` points just past the opening bracket.
 */
export function getText(data, index) {
  let bracketCount = 1;
  let out = '';
  let pos = index;
  for (; pos < data.length; pos += 1) {
    const c = data[pos];
    if (c === ']') bracketCount -= 1;
    else if (c === '[') bracketCount += 1;
    if (bracketCount === 0) {
      pos += 1;
      break;
    }
    out += c;
  }
  return { text: out, index: pos, handled: bracketCount === 0 };
}

/** Collapse every whitespace run in a title to single spaces. */
function cleanTitle(title) {
  let out = '';
  for (let i = 0; i < title.length; i += 1) {
    out += isWhitespace(title[i]) ? ' ' : title[i];
  }
  return out;
}

/**
 * Parse `(href "title")` starting at `index` (which must point at the `(`).
 * Returns `{ href, title, index, handled }`.
 */
export function getLink(data, index) {
  if (data[index] !== '(') return { href: '', title: null, index, handled: false };
  let pos = index + 1;
  let href = '';
  let title = null;

  while (pos < data.length && isWhitespace(data[pos])) pos += 1;

  if (data[pos] === '<') {
    const close = data.indexOf('>', pos + 1);
    if (close === -1) return { href: '', title: null, index, handled: false };
    href = data.slice(pos + 1, close);
    pos = close + 1;
  } else {
    let depth = 0;
    let start = pos;
    while (pos < data.length) {
      const c = data[pos];
      if (c === '(') depth += 1;
      else if (c === ')') {
        if (depth === 0) break;
        depth -= 1;
      } else if (isWhitespace(c) && depth === 0) break;
      pos += 1;
    }
    href = data.slice(start, pos);
  }

  while (pos < data.length && isWhitespace(data[pos])) pos += 1;

  const opener = data[pos];
  if (opener === '"' || opener === "'") {
    // The title runs to the last matching quote before the closing paren.
    let scan = pos + 1;
    let close = -1;
    while (scan < data.length) {
      if (data[scan] === opener) {
        let after = scan + 1;
        while (after < data.length && isWhitespace(data[after])) after += 1;
        if (data[after] === ')') {
          close = scan;
          break;
        }
      }
      scan += 1;
    }
    if (close !== -1) {
      title = cleanTitle(data.slice(pos + 1, close));
      pos = close + 1;
      while (pos < data.length && isWhitespace(data[pos])) pos += 1;
    }
  }

  if (data[pos] !== ')') return { href: '', title: null, index, handled: false };
  return { href: strip(href), title, index: pos + 1, handled: true };
}

/** Parse the `[id]` that follows a reference label. */
export function evalId(data, index) {
  let pos = index;
  while (pos < data.length && isWhitespace(data[pos])) pos += 1;
  if (data[pos] !== '[') return { id: null, index, handled: false };
  const close = data.indexOf(']', pos + 1);
  if (close === -1) return { id: null, index, handled: false };
  return { id: data.slice(pos + 1, close), index: close + 1, handled: true };
}

function normalizeId(id) {
  let out = '';
  for (let i = 0; i < id.length; i += 1) {
    out += isWhitespace(id[i]) ? ' ' : id[i];
  }
  return strip(out).toLowerCase();
}

export function makeLink(href, title, text) {
  const el = new Element('a');
  el.set('href', href);
  if (title !== null && title !== undefined) el.set('title', title);
  el.text = text;
  return el;
}

export function makeImage(href, title, alt) {
  const el = new Element('img');
  el.set('src', href);
  if (title !== null && title !== undefined) el.set('title', title);
  el.set('alt', atomic(alt));
  return el;
}

/** `[text](href "title")` */
export function handleLink(md, data, trigger) {
  const label = getText(data, trigger.end);
  if (!label.handled) return null;
  const link = getLink(data, label.index);
  if (!link.handled) return null;
  return {
    node: makeLink(link.href, link.title, label.text),
    start: trigger.start,
    end: link.index,
  };
}

/** `![alt](src "title")` */
export function handleImage(md, data, trigger) {
  const label = getText(data, trigger.end);
  if (!label.handled) return null;
  const link = getLink(data, label.index);
  if (!link.handled) return null;
  return {
    node: makeImage(link.href, link.title, label.text),
    start: trigger.start,
    end: link.index,
  };
}

function lookupReference(md, id) {
  return md.references.get(normalizeId(id));
}

/** `[text][id]` and `![alt][id]` */
export function handleReference(md, data, trigger, isImage) {
  const label = getText(data, trigger.end);
  if (!label.handled) return null;
  const ref = evalId(data, label.index);
  if (!ref.handled) return null;
  const id = ref.id === '' ? label.text : ref.id;
  const found = lookupReference(md, id);
  if (found === undefined) return { node: null, start: trigger.start, end: ref.index };
  const node = isImage
    ? makeImage(found.href, found.title, label.text)
    : makeLink(found.href, found.title, label.text);
  return { node, start: trigger.start, end: ref.index };
}

/** `[id]` and `![id]` -- the label doubles as the reference id. */
export function handleShortReference(md, data, trigger, isImage) {
  const label = getText(data, trigger.end);
  if (!label.handled) return null;
  const found = lookupReference(md, label.text);
  if (found === undefined) return { node: null, start: trigger.start, end: label.index };
  const node = isImage
    ? makeImage(found.href, found.title, label.text)
    : makeLink(found.href, found.title, label.text);
  return { node, start: trigger.start, end: label.index };
}

