        }
        return null;
      },
      handle: (data, t) => ({ node: t.text, start: t.start, end: t.end }),
    }, 'not_strong', 70);

    this.register({
      find: (data, start) => findDelimiter(data, start, '*'),
      handle: (data, t) => this.asterisk.handleMatch(data, t),
    }, 'em_strong', 60);

    this.register({
      find: (data, start) => findDelimiter(data, start, '_'),
      handle: (data, t) => this.underscore.handleMatch(data, t),
    }, 'em_strong2', 50);
  }

  // ---------------------------------------------------------------- placeholders

  stashNode(node, patternIndex) {
    const id = padId(this.stashedNodes.size);
    this.stashedNodes.set(id, { node, patternIndex });
    return INLINE_PLACEHOLDER_PREFIX + id + ETX;
  }

  /** Expand inline placeholders back to serialized markup (for raw HTML). */
  unescape(text) {
    if (text.indexOf(INLINE_PLACEHOLDER_PREFIX) === -1) return text;
    let out = '';
    let i = 0;
    while (i < text.length) {
      const at = text.indexOf(INLINE_PLACEHOLDER_PREFIX, i);
      if (at === -1) {
        out += text.slice(i);
        break;
      }
      out += text.slice(i, at);
      const idStart = at + INLINE_PLACEHOLDER_PREFIX.length;
      const idEnd = text.indexOf(ETX, idStart);
      if (idEnd === -1) {
        out += text.slice(at);
        break;
      }
      const id = text.slice(idStart, idEnd);
      const stashed = this.stashedNodes.get(id);
      if (stashed === undefined) {
        out += text.slice(at, idEnd + 1);
      } else if (typeof stashed.node === 'string') {
        out += stashed.node;
      } else {
        out += serialize(stashed.node);
      }
      i = idEnd + 1;
    }
    return out;
  }

  /** Turn `STX<code>ETX` sentinels back into their characters. */
  backslashUnescape(text) {
    return unescapeSentinels(text);
  }

  // ------------------------------------------------------------------- scanning

  handleInline(data, patternIndex = 0) {
    let text = data;
    let index = patternIndex;
    while (index < this.patterns.length) {
      const result = this.applyPattern(this.patterns[index], text, index);
      text = result.data;
      if (!result.matched) index += 1;
    }
    return text;
  }

  applyPattern(pattern, data, patternIndex) {
    let startIndex = 0;
    let text = data;
    while (true) {
      const trigger = pattern.find(text, startIndex);
      if (trigger === null) return { data: text, matched: false };
      const result = pattern.handle(text, trigger);
      if (result === null || result.node === null || result.node === undefined) {
        // Rejected: keep looking further along the string.
        startIndex = result === null ? trigger.end : Math.max(result.end, trigger.end);
        if (startIndex > text.length) return { data: text, matched: false };
        continue;
      }
      const placeholder = this.stashNode(result.node, patternIndex);
      text = text.slice(0, result.start) + placeholder + text.slice(result.end);
      return { data: text, matched: true };
    }
  }

  /**
   * Turn a placeholder-bearing string into `{ leading, nodes }` where `nodes`
   * carry their own tails -- exactly the shape an element tree wants.
   */
  expand(data, patternIndex) {
    const nodes = [];
    let leading = null;
    const addText = (text) => {
      if (text === '') return;
      if (nodes.length > 0) {
        const last = nodes[nodes.length - 1];
        last.tail = (last.tail === null ? '' : String(last.tail)) + text;
      } else {
        leading = (leading === null ? '' : leading) + text;
      }
    };

    let i = 0;
    while (i < data.length) {
      const at = data.indexOf(INLINE_PLACEHOLDER_PREFIX, i);
      if (at === -1) {
        addText(data.slice(i));
        break;
      }
      addText(data.slice(i, at));
      const idStart = at + INLINE_PLACEHOLDER_PREFIX.length;
      const idEnd = data.indexOf(ETX, idStart);
      const id = idEnd === -1 ? null : data.slice(idStart, idEnd);
      const stashed = id === null ? undefined : this.stashedNodes.get(id);
      if (stashed === undefined) {
        addText(data.slice(at, at + INLINE_PLACEHOLDER_PREFIX.length));
        i = at + INLINE_PLACEHOLDER_PREFIX.length;
        continue;
      }
      if (typeof stashed.node === 'string') {
        addText(stashed.node);
      } else {
        this.processGenerated(stashed.node, stashed.patternIndex);
        this.generated.add(stashed.node);
        nodes.push(stashed.node);
      }
      i = idEnd + 1;
    }
    return { leading, nodes };
  }

  /** Recursively finish an element produced by a pattern. */
  processGenerated(el, patternIndex) {
    if (el.text !== null && !isAtomic(el.text)) {
      const expanded = this.expand(this.handleInline(String(el.text), patternIndex + 1));
      el.text = expanded.leading;
      expanded.nodes.forEach((node, offset) => el.insert(offset, node));
    }
    let i = 0;
    while (i < el.children.length) {
      const child = el.children[i];
      if (!this.generated.has(child)) {
        this.processGenerated(child, patternIndex);
        this.generated.add(child);
      }
      if (child.tail !== null && !isAtomic(child.tail)) {
        const expanded = this.expand(this.handleInline(String(child.tail), patternIndex));
        child.tail = expanded.leading;
        expanded.nodes.forEach((node, offset) => el.insert(i + 1 + offset, node));
        i += expanded.nodes.length;
      }
      i += 1;
    }
  }

  // ---------------------------------------------------------------------- entry

  run(root) {
    this.stashedNodes = new Map();
    this.processTree(root);
    return root;
  }

  processTree(el) {
    if (el.text !== null && !isAtomic(el.text)) {
      const expanded = this.expand(this.handleInline(String(el.text), 0));
      el.text = expanded.leading;
      expanded.nodes.forEach((node, offset) => el.insert(offset, node));
    }
    let i = 0;
    while (i < el.children.length) {
      const child = el.children[i];
      if (!this.generated.has(child)) this.processTree(child);
      if (child.tail !== null && !isAtomic(child.tail) && !this.generated.has(child)) {
        const expanded = this.expand(this.handleInline(String(child.tail), 0));
        child.tail = expanded.leading;
        expanded.nodes.forEach((node, offset) => el.insert(i + 1 + offset, node));
        i += expanded.nodes.length;
      }
      i += 1;
    }
  }
}

function stripSpaces(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isWhitespace(text[start])) start += 1;
  while (end > start && isWhitespace(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

/** Replace `STX<digits>ETX` sentinels with the characters they stand for. */
export function unescapeSentinels(text) {
  if (text.indexOf(STX) === -1) return text;
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] !== STX) {
      out += text[i];
      i += 1;
      continue;
    }
    let j = i + 1;
    while (j < text.length && isDigit(text[j])) j += 1;
    if (j > i + 1 && text[j] === ETX) {
      out += String.fromCodePoint(Number(text.slice(i + 1, j)));
      i = j + 1;
    } else {
      out += text[i];
      i += 1;
    }
  }
  return out;
}

