// The inline treeprocessor.
//
// Patterns are applied one at a time to the *whole* string, each match being
// swapped for a sentinel placeholder before the next pattern runs. That
// ordering is observable -- it is why a code span wins over emphasis even when
// the emphasis delimiter appears first -- so it is reproduced exactly.

import { Element, atomic, isAtomic } from '../element.mjs';
import {
  AMP_SUBSTITUTE, ESCAPED_CHARS, ETX, INLINE_PLACEHOLDER_PREFIX, STX,
} from '../constants.mjs';
import { isDigit, isWhitespace } from '../chars.mjs';
import { codeEscape } from '../blockpatterns.mjs';
import { matchEntity, codepointToName } from '../entities.mjs';
import { matchTag, TAG_COMMENT, TAG_END, TAG_START, TAG_STARTEND } from '../htmltokenizer.mjs';
import { EmStrongProcessor, matchNotStrong } from './emphasis.mjs';
import {
  handleImage, handleLink, handleReference, handleShortReference,
} from './links.mjs';
import { serialize } from '../serializer.mjs';

const ESCAPED_BSLASH = STX + '92' + ETX;

function padId(index) {
  return String(index).padStart(4, '0');
}

/** Find the next backtick run that is not backslash escaped. */
function findBacktick(data, startIndex) {
  let i = startIndex;
  while (i < data.length) {
    if (data[i] !== '`') {
      i += 1;
      continue;
    }
    if (i > 0 && data[i - 1] === '\\') {
      i += 1;
      continue;
    }
    let run = 0;
    while (data[i + run] === '`') run += 1;
    // Look for a closing run of exactly the same length.
    let j = i + run;
    while (j < data.length) {
      if (data[j] !== '`') {
        j += 1;
        continue;
      }
      let closing = 0;
      while (data[j + closing] === '`') closing += 1;
      if (closing === run && j > i + run) {
        return { start: i, end: j + run, contentStart: i + run, contentEnd: j };
      }
      j += closing;
    }
    i += run;
  }
  return null;
}

function findChar(data, startIndex, ch) {
  const at = data.indexOf(ch, startIndex);
  return at === -1 ? null : { start: at, end: at + 1 };
}

/** `[` not preceded by `!`. */
function findLinkBracket(data, startIndex) {
  let i = startIndex;
  while (true) {
    const at = data.indexOf('[', i);
    if (at === -1) return null;
    if (at === 0 || data[at - 1] !== '!') return { start: at, end: at + 1 };
    i = at + 1;
  }
}

function findImageBracket(data, startIndex) {
  const at = data.indexOf('![', startIndex);
  return at === -1 ? null : { start: at, end: at + 2 };
}

const AUTOLINK_SCHEMES = ['http://', 'https://', 'ftp://', 'ftps://'];

function findAutolink(data, startIndex) {
  let i = startIndex;
  while (true) {
    const at = data.indexOf('<', i);
    if (at === -1) return null;
    const close = data.indexOf('>', at + 1);
    if (close === -1) return null;
    const inner = data.slice(at + 1, close);
    if (inner.indexOf('<') === -1) {
      const lowered = inner.toLowerCase();
      for (const scheme of AUTOLINK_SCHEMES) {
        if (lowered.startsWith(scheme)) {
          return { start: at, end: close + 1, inner };
        }
      }
    }
    i = at + 1;
  }
}

/** `<([^<> !]+@[^@<> ]+)>` */
function findAutomail(data, startIndex) {
  let i = startIndex;
  while (true) {
    const at = data.indexOf('<', i);
    if (at === -1) return null;
    const close = data.indexOf('>', at + 1);
    if (close === -1) return null;
    const inner = data.slice(at + 1, close);
    const split = inner.indexOf('@');
    if (split > 0 && split < inner.length - 1) {
      const local = inner.slice(0, split);
      const domain = inner.slice(split + 1);
      const badLocal = local.indexOf('<') !== -1 || local.indexOf('>') !== -1 ||
        local.indexOf(' ') !== -1;
      const badDomain = domain.indexOf('@') !== -1 || domain.indexOf('<') !== -1 ||
        domain.indexOf('>') !== -1 || domain.indexOf(' ') !== -1;
      if (!badLocal && !badDomain) return { start: at, end: close + 1, inner };
    }
    i = at + 1;
  }
}

function findLineBreak(data, startIndex) {
  const at = data.indexOf('  \n', startIndex);
  return at === -1 ? null : { start: at, end: at + 3 };
}

function findInlineHtml(data, startIndex) {
  let i = startIndex;
  while (true) {
    const at = data.indexOf('<', i);
    if (at === -1) return null;
    const tag = matchTag(data, at);
    if (tag !== null &&
      (tag.kind === TAG_START || tag.kind === TAG_END ||
        tag.kind === TAG_STARTEND || tag.kind === TAG_COMMENT)) {
      return { start: at, end: tag.end, raw: tag.text };
    }
    i = at + 1;
  }
}

function findEntity(data, startIndex) {
  let i = startIndex;
  while (true) {
    const at = data.indexOf('&', i);
    if (at === -1) return null;
    const end = matchEntity(data, at);
    if (end !== -1) return { start: at, end, raw: data.slice(at, end) };
    i = at + 1;
  }
}

function findDelimiter(data, startIndex, ch) {
  const at = data.indexOf(ch, startIndex);
  return at === -1 ? null : { start: at, end: at + 1 };
}

