    this.register({
      find: findLineBreak,
      handle: (data, t) => ({ node: new Element('br'), start: t.start, end: t.end }),
    }, 'linebreak', 100);

    this.register({
      find: findInlineHtml,
      handle: (data, t) => {
        const raw = this.backslashUnescape(this.unescape(t.raw));
        return { node: md.htmlStash.store(raw), start: t.start, end: t.end, rawHtml: true };
      },
    }, 'html', 90);

    this.register({
      find: findEntity,
      handle: (data, t) => {
        const raw = this.backslashUnescape(this.unescape(t.raw));
        return { node: md.htmlStash.store(raw), start: t.start, end: t.end, rawHtml: true };
