// Whitespace and escape-restoration tree passes.

import { isBlockLevel } from './constants.mjs';
import { atomic, isAtomic } from './element.mjs';
import { isBlank, rstrip } from './chars.mjs';
import { unescapeSentinels } from './inline/processor.mjs';

/**
 * Insert newlines so the serialized document is readable. This is what produces
 * the reference implementation's characteristic layout, including the absence of
 * a newline between an `<li>`'s text and a nested list.
 */
export class PrettifyTreeprocessor {
  prettify(elem) {
    const nl = '\n';
    if (isBlockLevel(elem.tag) && elem.tag !== 'code' && elem.tag !== 'pre') {
      const textBlank = elem.text === null || isBlank(String(elem.text));
      if (textBlank && elem.children.length > 0 && isBlockLevel(elem.children[0].tag)) {
        elem.text = nl;
      }
      for (const child of elem.children) {
        if (isBlockLevel(child.tag)) this.prettify(child);
      }
      if (elem.tail === null || isBlank(String(elem.tail))) elem.tail = nl;
    }
  }

  run(root) {
    this.prettify(root);

    // `<br />` usually sits mid-line, so handle it separately.
    for (const el of root.iter('br')) {
      if (el.tail === null || isBlank(String(el.tail))) el.tail = '\n';
      else el.tail = '\n' + String(el.tail);
    }

    // Trim the blank lines blank-line handling may have appended to code blocks.
    for (const pre of root.iter('pre')) {
      if (pre.children.length > 0 && pre.children[0].tag === 'code') {
        const code = pre.children[0];
        if (code.children.length === 0 && code.text !== null) {
          code.text = atomic(rstrip(String(code.text)) + '\n');
        }
      }
    }
    return root;
  }
}

/** Turn the escape sentinels back into real characters. */
export class UnescapeTreeprocessor {
  run(root) {
    for (const el of root.iter()) {
      if (el.text !== null && el.tag !== 'code') {
        const value = unescapeSentinels(String(el.text));
        el.text = isAtomic(el.text) ? atomic(value) : value;
      }
      if (el.tail !== null) {
        const value = unescapeSentinels(String(el.tail));
        el.tail = isAtomic(el.tail) ? atomic(value) : value;
      }
      for (const [key, value] of [...el.attrib]) {
        if (typeof value === 'string') el.set(key, unescapeSentinels(value));
      }
    }
    return root;
  }
}

