// Text level passes that run after serialization.

import { AMP_SUBSTITUTE } from './constants.mjs';
import { isBlockLevel } from './constants.mjs';
import { isAsciiLetter } from './chars.mjs';

/**
 * Does a stashed fragment start with a block level tag? Block level fragments
 * shed the `<p>` wrapper the block parser gave their placeholder.
 */
function isBlockLevelHtml(html) {
  if (html[0] !== '<') return false;
  let i = 1;
  if (html[i] === '/') i += 1;
  const first = html[i];
  if (first === undefined) return false;
  if (first === '!' || first === '?' || first === '@' || first === '%') return true;
  if (!isAsciiLetter(first)) return false;
  let end = i;
  while (end < html.length && html[end] !== ' ' && html[end] !== '>') end += 1;
  return isBlockLevel(html.slice(i, end));
}

/** Swap stash placeholders back for the raw HTML they stand for. */
export class RawHtmlPostprocessor {
  constructor(md) {
    this.md = md;
  }

  run(text) {
    const stash = this.md.htmlStash;
    if (stash.length === 0) return text;

    // Longest keys first so `<p>PH</p>` wins over a bare `PH`.
    const replacements = [];
    for (let i = 0; i < stash.length; i += 1) {
      const html = stash.get(i);
      const placeholder = stash.getPlaceholder(i);
      if (isBlockLevelHtml(html)) {
        replacements.push(['<p>' + placeholder + '</p>', html]);
      }
      replacements.push([placeholder, html]);
    }
    replacements.sort((a, b) => b[0].length - a[0].length);

    let out = text;
    for (const [key, value] of replacements) {
      if (out.indexOf(key) === -1) continue;
      out = out.split(key).join(value);
    }
    return out;
  }
}

/** Restore the ampersand sentinel. */
export class AndSubstitutePostprocessor {
  run(text) {
    return text.split(AMP_SUBSTITUTE).join('&');
  }
}

