// Preprocessors: whole-document passes that run on the list of lines before
// block parsing starts.

import { STX, ETX, TAB_LENGTH } from './constants.mjs';
import { expandTabs } from './chars.mjs';
import { extractHtmlBlocks } from './htmlblocks.mjs';

/**
 * Line ending normalisation, tab expansion and blanking of whitespace-only
 * lines. Two newlines are appended so the final block always terminates.
 */
export class NormalizeWhitespace {
  constructor(md) {
    this.md = md;
  }

  run(lines) {
    let source = lines.join('\n');
    source = source.split(STX).join('').split(ETX).join('');
    source = source.split('\r\n').join('\n').split('\r').join('\n') + '\n\n';
    source = expandTabs(source, TAB_LENGTH);

    // `(?<=\n) +\n` -> `\n`: a line of nothing but spaces becomes empty.
    const parts = source.split('\n');
    for (let i = 1; i < parts.length; i += 1) {
      const part = parts[i];
      if (part.length === 0) continue;
      let onlySpaces = true;
      for (let k = 0; k < part.length; k += 1) {
        if (part[k] !== ' ') { onlySpaces = false; break; }
      }
      if (onlySpaces) parts[i] = '';
    }
    return parts;
  }
}

/** Pull top level raw HTML out of the document. */
export class HtmlBlockPreprocessor {
  constructor(md) {
    this.md = md;
  }

  run(lines) {
    const source = lines.join('\n');
    return extractHtmlBlocks(source, this.md.htmlStash).split('\n');
  }
}

