// Markdown façade: wires the pipeline together and applies extensions.
//
// Pipeline order mirrors the reference implementation:
//   preprocessors -> block parser -> treeprocessors -> serializer -> postprocessors

import { BlockParser } from './blockparser.mjs';
import { buildBlockParser } from './blockprocessors.mjs';
import { HtmlStash } from './stash.mjs';
import { HtmlBlockPreprocessor, NormalizeWhitespace } from './preprocessors.mjs';
import { InlineTreeprocessor } from './inline/processor.mjs';
import { PrettifyTreeprocessor, UnescapeTreeprocessor } from './treeprocessors.mjs';
import { AndSubstitutePostprocessor, RawHtmlPostprocessor } from './postprocessors.mjs';
import { serialize } from './serializer.mjs';
import { isBlank, strip } from './chars.mjs';
import { isBlockLevel, TAB_LENGTH } from './constants.mjs';
import { EXTENSIONS } from './extensions/index.mjs';

/** Priority-ordered registry (highest priority first). */
class Registry {
  constructor() {
    this.entries = [];
  }

  register(item, name, priority) {
    this.deregister(name);
    this.entries.push({ item, name, priority });
    this.entries.sort((a, b) => b.priority - a.priority);
  }

  deregister(name) {
    this.entries = this.entries.filter((entry) => entry.name !== name);
  }

  has(name) {
    return this.entries.some((entry) => entry.name === name);
  }

  get(name) {
    const found = this.entries.find((entry) => entry.name === name);
    return found === undefined ? null : found.item;
  }

  *[Symbol.iterator]() {
    for (const entry of this.entries) yield entry.item;
  }
}

export class Markdown {
  constructor(extensions = []) {
    this.docTag = 'div';
    this.tabLength = TAB_LENGTH;
    this.stripTopLevelTags = true;
    this.references = new Map();
    this.htmlStash = new HtmlStash();
    this.extensionNames = [];

    this.preprocessors = new Registry();
    this.treeprocessors = new Registry();
    this.postprocessors = new Registry();

    this.parser = new BlockParser(this);
    buildBlockParser(this, this.parser);

    this.inlineProcessor = new InlineTreeprocessor(this);

    this.preprocessors.register(new NormalizeWhitespace(this), 'normalize_whitespace', 30);
    this.preprocessors.register(new HtmlBlockPreprocessor(this), 'html_block', 20);

    this.treeprocessors.register(this.inlineProcessor, 'inline', 20);
    this.treeprocessors.register(new PrettifyTreeprocessor(this), 'prettify', 10);
    this.treeprocessors.register(new UnescapeTreeprocessor(this), 'unescape', 0);

    this.postprocessors.register(new RawHtmlPostprocessor(this), 'raw_html', 30);
    this.postprocessors.register(new AndSubstitutePostprocessor(), 'amp_substitute', 20);

    this.registerExtensions(extensions);
  }

  isBlockLevel(tag) {
    return isBlockLevel(tag);
  }

  registerExtensions(extensions) {
    for (const name of extensions) {
      const factory = EXTENSIONS[name];
      if (factory === undefined) {
        throw new Error("Failed loading extension '" + name + "'.");
      }
      this.extensionNames.push(name);
    }
    // `extra` pulls in its own bundle; expand before wiring anything up.
    const expanded = [];
    for (const name of this.extensionNames) {
      if (name === 'extra') {
        for (const sub of EXTRA_BUNDLE) {
          if (!expanded.includes(sub)) expanded.push(sub);
        }
      } else if (!expanded.includes(name)) {
        expanded.push(name);
      }
    }
    this.activeExtensions = expanded;
    for (const name of expanded) EXTENSIONS[name](this);
  }

  hasExtension(name) {
    return this.activeExtensions.includes(name);
  }

  reset() {
    this.htmlStash.reset();
    this.references.clear();
    return this;
  }

  convert(source) {
    if (isBlank(source)) return '';

    let lines = String(source).split('\n');
    for (const prep of this.preprocessors) lines = prep.run(lines);

    const root = this.parser.parseDocument(lines);

    let tree = root;
    for (const treeprocessor of this.treeprocessors) {
      const replacement = treeprocessor.run(tree);
      if (replacement !== undefined && replacement !== null) tree = replacement;
    }

    let output = serialize(tree);
    if (this.stripTopLevelTags) {
      const openTag = '<' + this.docTag + '>';
      const closeTag = '</' + this.docTag + '>';
      const start = output.indexOf(openTag);
      const end = output.lastIndexOf(closeTag);
      if (start !== -1 && end !== -1) {
        output = strip(output.slice(start + openTag.length, end));
      } else if (strip(output).endsWith('<' + this.docTag + ' />')) {
        output = '';
      }
    }

    for (const pp of this.postprocessors) output = pp.run(output);
    return strip(output);
  }
}

const EXTRA_BUNDLE = [
  'abbr', 'attr_list', 'def_list', 'fenced_code', 'footnotes', 'md_in_html', 'tables',
];

/** Convenience wrapper matching `markdown.markdown(text, extensions=[...])`. */
export function markdown(text, extensions = []) {
  return new Markdown(extensions).convert(text);
}

