  registerExtensions(extensions) {
    for (const name of extensions) {
      const factory = EXTENSIONS[name];
      if (factory === undefined) {
        throw new Error("Failed loading extension '" + name + "'.");
      }
      this.extensionNames.push(name);
    }
    // `extra` pulls in its own bundle; expand before wiring anything up.
    const expanded = [];
    for (const name of this.extensionNames) {
      if (name === 'extra') {
        for (const sub of EXTRA_BUNDLE) {
          if (!expanded.includes(sub)) expanded.push(sub);
        }
      } else if (!expanded.includes(name)) {
