  }

  convert(source) {
    if (isBlank(source)) return '';

    let lines = String(source).split('\n');
    for (const prep of this.preprocessors) lines = prep.run(lines);

    const root = this.parser.parseDocument(lines);

    let tree = root;
    for (const treeprocessor of this.treeprocessors) {
      const replacement = treeprocessor.run(tree);
      if (replacement !== undefined && replacement !== null) tree = replacement;
    }

    let output = serialize(tree);
    if (this.stripTopLevelTags) {
      const openTag = '<' + this.docTag + '>';
      const closeTag = '</' + this.docTag + '>';
      const start = output.indexOf(openTag);
      const end = output.lastIndexOf(closeTag);
