import { subElement } from '../element.mjs';
import { stripChars } from '../chars.mjs';

/**
 * Split a row on unescaped pipes that are not inside a code span.
 * Mirrors the reference implementation's `_split`, which pairs up backtick runs
 * and discards any pipe falling inside a pair.
 */
function splitCells(row) {
  const cells = [];
  let current = '';
  let i = 0;
  while (i < row.length) {
    const ch = row[i];
    if (ch === '\\' && (row[i + 1] === '|' || row[i + 1] === '\\' || row[i + 1] === '`')) {
      current += ch + row[i + 1];
      i += 2;
      continue;
    }
    if (ch === '`') {
      let run = 0;
      while (row[i + run] === '`') run += 1;
      const fence = row.slice(i, i + run);
      const close = row.indexOf(fence, i + run);
      if (close !== -1) {
        current += row.slice(i, close + run);
        i = close + run;
        continue;
      }
      current += fence;
      i += run;
      continue;
    }
    if (ch === '|') {
      cells.push(current);
      current = '';
      i += 1;
      continue;
    }
    current += ch;
    i += 1;
  }
  cells.push(current);
  return cells;
}

/** `(?<!\\)(?:\\\\)*\|$` -- a trailing, unescaped table border. */
function stripEndBorder(row) {
  if (!row.endsWith('|')) return row;
  let backslashes = 0;
  let i = row.length - 2;
  while (i >= 0 && row[i] === '\\') {
    backslashes += 1;
    i -= 1;
  }
  if (backslashes % 2 === 1) return row;
  return row.slice(0, -1);
}

const SEPARATOR_CHARS = new Set(['|', ':', '-', ' ']);

export class TableProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.border = false;
    this.separator = [];
  }

  splitRow(row) {
    let text = row;
    if (this.border) {
      if (text.startsWith('|')) text = text.slice(1);
      text = stripEndBorder(text);
    }
    return splitCells(text);
  }

  test(parent, block) {
    let isTable = false;
    const rows = block.split('\n').map((row) => stripChars(row, ' '));
    if (rows.length > 1) {
      const header = rows[0];
      this.border = header.startsWith('|');
      const headerCells = this.splitRow(header);
      const width = headerCells.length;
      isTable = width > 1;

      if (!isTable && width === 1 && this.border) {
        for (let index = 1; index < rows.length; index += 1) {
          isTable = rows[index].startsWith('|') ||
            stripEndBorder(rows[index]) !== rows[index];
          if (!isTable) break;
        }
      }

      if (isTable) {
        const separator = this.splitRow(rows[1]);
        isTable = separator.length === width;
        if (isTable) {
          for (const ch of separator.join('')) {
            if (!SEPARATOR_CHARS.has(ch)) { isTable = false; break; }
          }
        }
        if (isTable) this.separator = separator;
      }
    }
    return isTable;
  }

  run(parent, blocks) {
    const block = blocks.shift().split('\n');
    const header = stripChars(block[0], ' ');
    const rows = block.length < 3 ? [] : block.slice(2);

    const align = this.separator.map((cell) => {
      const value = stripChars(cell, ' ');
      if (value.startsWith(':') && value.endsWith(':') && value.length > 1) return 'center';
      if (value.startsWith(':')) return 'left';
      if (value.endsWith(':')) return 'right';
      return null;
    });

    const table = subElement(parent, 'table');
    const thead = subElement(table, 'thead');
    this.buildRow(header, thead, align);
    const tbody = subElement(table, 'tbody');
    if (rows.length === 0) {
      const tr = subElement(tbody, 'tr');
      for (let i = 0; i < align.length; i += 1) subElement(tr, 'td');
    } else {
      for (const row of rows) this.buildRow(stripChars(row, ' '), tbody, align);
    }
    return undefined;
  }

  buildRow(row, parent, align) {
    const tr = subElement(parent, 'tr');
    const tag = parent.tag === 'thead' ? 'th' : 'td';
    const cells = this.splitRow(row);
    align.forEach((alignment, index) => {
      const cell = subElement(tr, tag);
      cell.text = index < cells.length ? stripChars(cells[index], ' ') : '';
      if (alignment !== null) cell.set('style', 'text-align: ' + alignment + ';');
    });
  }
}

export function tablesExtension(md) {
  md.parser.register(new TableProcessor(md.parser), 'table', 75);
}

