// `fenced_code` extension.
//
// Fenced blocks are converted straight to HTML and pushed into the raw HTML
// stash, so they bypass block and inline parsing entirely.

import { countLeadingSpaces, isAsciiAlnum, rstripChars } from '../chars.mjs';

function escapeCode(text) {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else if (ch === '"') out += '&quot;';
    else out += ch;
  }
  return out;
}

function isLangChar(ch) {
  return isAsciiAlnum(ch) || ch === '#' || ch === '.' || ch === '+' || ch === '-' ||
    ch === '_';
}

/** Recognise an opening fence, returning `{ fence, lang, indent }`. */
function matchOpeningFence(line) {
  const indent = countLeadingSpaces(line);
  const rest = line.slice(indent);
  const marker = rest[0];
  if (marker !== '`' && marker !== '~') return null;
  let run = 0;
  while (rest[run] === marker) run += 1;
  if (run < 3) return null;
  let i = run;
  while (rest[i] === ' ') i += 1;

  let lang = '';
  if (rest[i] === '{') {
    // `{.lang}` attribute form; take the first class-ish token.
    const close = rest.indexOf('}', i);
    if (close === -1) return null;
    let token = rest.slice(i + 1, close);
    while (token.startsWith('.')) token = token.slice(1);
    let end = 0;
    while (end < token.length && isLangChar(token[end])) end += 1;
    lang = token.slice(0, end);
    i = close + 1;
  } else {
    if (rest[i] === '.') i += 1;
    const start = i;
    while (i < rest.length && isLangChar(rest[i])) i += 1;
    lang = rest.slice(start, i);
  }
  while (rest[i] === ' ') i += 1;
  if (i !== rest.length) return null;
  return { fence: marker.repeat(run), lang, indent };
}

/** Is this line a closing fence for `fence`? */
function isClosingFence(line, fence) {
  const trimmed = rstripChars(line, ' ');
  const indent = countLeadingSpaces(trimmed);
  const rest = trimmed.slice(indent);
  if (!rest.startsWith(fence)) return false;
  for (let i = 0; i < rest.length; i += 1) {
    if (rest[i] !== fence[0]) return false;
  }
  return true;
}

export class FencedBlockPreprocessor {
  constructor(md) {
    this.md = md;
    this.langPrefix = 'language-';
  }

  run(lines) {
    const out = [];
    let i = 0;
    while (i < lines.length) {
      const opening = matchOpeningFence(lines[i]);
      if (opening === null) {
        out.push(lines[i]);
        i += 1;
        continue;
      }
      // Find the closing fence; without one the block is left as plain text.
      let close = -1;
      for (let j = i + 1; j < lines.length; j += 1) {
        if (isClosingFence(lines[j], opening.fence)) { close = j; break; }
      }
      if (close === -1) {
        out.push(lines[i]);
        i += 1;
        continue;
      }
      const body = lines.slice(i + 1, close).join('\n');
      out.push(this.md.htmlStash.store(this.render(body, opening.lang)));
      out.push('');
      i = close + 1;
    }
    return out;
  }

  render(body, lang) {
    const highlighter = this.md.codeHighlighter;
    const text = body === '' ? '' : body + '\n';
    if (highlighter !== null && highlighter !== undefined) {
      return highlighter.highlight(body, lang === '' ? null : lang);
    }
    const classAttr = lang === '' ? '' : ' class="' + this.langPrefix + lang + '"';
    return '<pre><code' + classAttr + '>' + escapeCode(text) + '</code></pre>';
  }
}

export function fencedCodeExtension(md) {
  md.preprocessors.register(new FencedBlockPreprocessor(md), 'fenced_code_block', 25);
}

