// `def_list` extension.

import { BlockProcessor } from '../blockparser.mjs';
import { subElement } from '../element.mjs';
import { ListIndentProcessor } from '../blockprocessors.mjs';
import { countLeadingSpaces, isBlank, strip } from '../chars.mjs';
import { detab, lineEnd, lineStarts } from '../blockpatterns.mjs';

/** `(^|\n)[ ]{0,3}:[ ]{1,3}(.*?)(\n|$)` */
function searchDefinition(block) {
  for (const start of lineStarts(block)) {
    const stop = lineEnd(block, start);
    const line = block.slice(start, stop);
    const indent = countLeadingSpaces(line);
    if (indent > 3) continue;
    if (line[indent] !== ':') continue;
    let i = indent + 1;
    let spaces = 0;
    while (spaces < 3 && line[i] === ' ') {
      spaces += 1;
      i += 1;
    }
    if (spaces < 1) continue;
    return {
      start: start === 0 ? 0 : start - 1,
      end: stop < block.length ? stop + 1 : stop,
      definition: line.slice(i),
    };
  }
  return null;
}

/** `^[ ]{0,3}[^ :]` */
function hasNoIndent(block) {
  const indent = countLeadingSpaces(block);
  if (indent > 3) return false;
  const ch = block[indent];
  return ch !== undefined && ch !== ' ' && ch !== ':';
}

export class DefListProcessor extends BlockProcessor {
  test(parent, block) {
    return searchDefinition(block) !== null;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const m = searchDefinition(block);
    if (m === null) {
      blocks.unshift(block);
      return false;
    }

    let terms = block
      .slice(0, m.start)
      .split('\n')
      .map((term) => strip(term))
      .filter((term) => term !== '');
    block = block.slice(m.end);

    let definition;
    let theRest = null;
    if (hasNoIndent(block)) {
      definition = block;
    } else {
      const [detabbed, rest] = detab(block);
      definition = detabbed;
      theRest = rest;
    }
    definition = definition !== '' ? m.definition + '\n' + definition : m.definition;

    let sibling = this.lastChild(parent);
    if (terms.length === 0 && sibling === null) {
      blocks.unshift(block);
      return false;
    }

    let state;
    if (terms.length === 0 && sibling.tag === 'p') {
      state = 'looselist';
      terms = String(sibling.text).split('\n');
      parent.remove(sibling);
      sibling = this.lastChild(parent);
    } else {
      state = 'list';
    }

    let dl;
    if (sibling !== null && sibling.tag === 'dl') {
      dl = sibling;
      const last = this.lastChild(dl);
      if (terms.length === 0 && last !== null && last.tag === 'dd' &&
        last.children.length > 0) {
        state = 'looselist';
      }
    } else {
      dl = subElement(parent, 'dl');
    }

    for (const term of terms) {
      const dt = subElement(dl, 'dt');
      dt.text = term;
    }

    this.parser.state.set(state);
    const dd = subElement(dl, 'dd');
    this.parser.parseBlocks(dd, [definition]);
    this.parser.state.reset();

    if (theRest !== null && !isBlank(theRest)) blocks.unshift(theRest);
    return undefined;
  }
}

/** Indented children of definition list items. */
export class DefListIndentProcessor extends ListIndentProcessor {
  constructor(parser) {
    super(parser);
    this.itemTypes = ['dd', 'li'];
    this.listTypes = ['dl', 'ol', 'ul'];
  }
}

export function defListExtension(md) {
  md.parser.register(new DefListIndentProcessor(md.parser), 'defindent', 85);
  md.parser.register(new DefListProcessor(md.parser), 'deflist', 25);
}

